-- Batch: feature_knowledge_seed_20260511T091258Z
-- This script upserts deterministic records and does not delete manual rows.

begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "8e861453-f6db-5992-b15e-41425c1ddc7d", "feature_slug": "referral", "title": "Referral Domain Reference", "content": "**Keywords:** referral, invite, invite code, inviter, invitee, referral code, signup referral, purchase referral, referral limit, referral reward\n**Source:** `Referral.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `fn_get_or_create_invite_code(user_id, merchant_id)` | `user_id (uuid)`, `merchant_id (uuid)` | VARCHAR invite code (8-char) | 321–341 |\n| `fn_process_referral_signup(invitee_user_id, invite_code)` | `invitee_user_id (uuid)`, `invite_code (varchar)` | JSONB: success status, referral details | 343–363 |\n**Key Business Rules (summary):**\n- One invite code per user per merchant (permanent, lazy-generated)\n- One referral per invitee per merchant (no double-dipping)\n- Activation trigger: `signup` (immediate reward) or `first_purchase` (reward after first buy)\n- Invitee rewards: direct distribution (points/tickets/rewards via wallet_ledger)\n- Inviter rewards: via mission system (referral_signup/referral_purchase condition types)\n- Limits configurable per user_type (buyer limits ≠ seller limits)", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/referral.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a25c8ed33a26733f306cb1907538d963569739e23379dd670df8109871043433", "truncated": false}, "is_active": true}, {"id": "430e271e-a694-586c-8e8b-fb068552c361", "feature_slug": "referral", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| `referral_active = false` | Invite code generation fails, signup with code is rejected |\n| `referral_active = true`, no outcomes configured | Referral ledger records are created but invitee receives nothing |\n| Activation trigger = `signup` | Invitee rewards distributed at registration, inviter mission queued |\n| Activation trigger = `first_purchase` | Invitee rewards deferred until first completed purchase |\n| Inviter at daily limit (e.g., 2/day, already has 2 today) | Next invitee signup with that inviter''s code is rejected |\n| Invitee already referred by another inviter | Signup with second invite code is rejected (one referral per invitee) |\n| Same invitee tries to use same code twice | Rejected — `UNIQUE(invitee_user_id, merchant_id)` constraint |\n| Invitee outcome = `reward`, entity_id = valid reward_id | Redemption ledger record created (qty 1), no points deducted |\n| Invitee outcome = `points`, amount = 100 | wallet_ledger entry: currency=points, component=bonus, source_type=referral |\n| Invitee outcome = `tickets`, entity_id = ticket_type_id | wallet_ledger entry: currency=ticket, component=base, source_type=referral |\n| Multiple outcomes configured | All outcomes distributed in single pass on activation |\n\n**Business rules as assertions:**\n\n- ASSERT: Each user has exactly one invite code per merchant (or none if never requested)\n- ASSERT: Each invitee can appear in referral_ledger at most once per merchant\n- ASSERT: Limit check counts referral_ledger records per inviter within the period window\n- ASSERT: `fn_process_referral_signup` validates code exists, invitee not already referred, inviter within limits — in that order\n- ASSERT: Purchase trigger only fires for `status = ''completed''` transactions\n- ASSERT: Purchase trigger only processes invitees with `first_purchase_at IS NULL`\n- ASSERT: Invitee rewards have `source_type = ''referral''` and `source_id = referral_ledger.id` in wallet_ledger\n- ASSERT: Mission evaluation queue receives event_type `referral_signup` or `referral_purchase` on activation\n- ASSERT: Invite code generation is idempotent — calling twice returns the same code\n\n**Error states to test:**\n\n- Referral program disabled (`referral_active = false`) — clear error returned\n- Invalid invite code — error with \"code not found\" messaging\n- Inviter limit exceeded — error specifying which period limit was hit\n- Invitee already referred — error indicating duplicate referral\n- Reward outcome with invalid entity_id — distribution fails for that outcome\n- Purchase trigger on non-completed transaction status — no processing occurs", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L158 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d0f80463e6040a24d47fe497c2bf35555870e85a5cc28673b3c2e0e99574c831", "truncated": false}, "is_active": true}, {"id": "b7088b1a-886c-5250-b1da-8eb42def8653", "feature_slug": "referral", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user` — **Frontend not yet built.** Steps below describe the backend-supported flow.\n\n**Route map:**\n\n| Page / Component | Planned route | Data source |\n|---|---|---|\n| Referral / Invite page | `/referral` or Homepage section | `fn_get_or_create_invite_code()` |\n| Signup Drawer | Bottom-sheet (existing) | `fn_process_referral_signup()` via `bff-auth-complete` |\n| Share sheet | Native OS share | Invite code + deep link |\n\n### 5a. Get and Share Invite Code\n\n1. Member navigates to referral page or taps \"Invite Friends\"\n2. System calls `fn_get_or_create_invite_code(user_id, merchant_id)` — returns existing code or generates a new one\n3. Member sees their permanent 8-character code with a share button\n4. Tapping share opens the native OS share sheet with the code and/or a deep link\n5. Code is the same every time — no regeneration\n\n### 5b. Invitee Signs Up with Code\n\n1. New user receives an invite code (via message, social media, etc.)\n2. During signup, the invite code field is pre-filled from the deep link or entered manually\n3. On registration completion, `fn_process_referral_signup` runs: validates code, checks inviter limits, creates ledger record\n4. If activation trigger is `signup`: invitee rewards are distributed immediately, inviter mission evaluation is queued\n5. If activation trigger is `first_purchase`: ledger record is created but rewards are deferred\n\n### 5c. Purchase-Triggered Activation\n\n1. Invitee makes their first purchase (any completed transaction)\n2. `trg_referral_purchase` trigger fires on `purchase_ledger` insert/update\n3. Trigger finds the invitee''s pending referral, updates `first_purchase_at`\n4. If merchant uses `first_purchase` trigger: invitee rewards distribute, inviter mission evaluation queues\n5. Invitee and inviter both receive their rewards after this point", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/referral.md#L122 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5d86ca54d2f2af5aefaead694e69ea3479b05f9a9e498253457d7d7e1fcb4563", "truncated": false}, "is_active": true}, {"id": "00bbf736-9e8b-5c63-b89a-d5cd0bb90ee2", "feature_slug": "referral", "title": "6b. For Marketing", "content": "**Value proposition:** Referral turns existing members into an acquisition channel. Two-sided rewards ensure both the sharer and the new member have incentive. The activation trigger choice lets merchants optimize for volume (signup-based) or quality (purchase-based).\n\n**Campaign ideas:**\n\n1. **Growth sprint** — Set activation to `signup`, configure generous invitee points (e.g., 200 points), create a milestone mission (\"Bronze Referrer: 1 signup → 200 pts, Silver: 3 → 500 pts, Gold: 5 → 1000 pts\"). High limits for sellers who have large networks.\n\n2. **Quality acquisition** — Set activation to `first_purchase`, offer a reward item (e.g., free product) as the invitee outcome. Inviter missions require `referral_purchase` conditions. Every referred user is a proven buyer.\n\n3. **Seasonal push** — Temporarily increase referral limits and invitee reward amounts for holiday periods. Limit periods (daily/weekly caps) prevent a single user from gaming the system even during promotions.\n\n**Metrics to track:** Invite codes generated (adoption), referral ledger entries (conversion), signup-to-purchase ratio (quality), limit utilization by user type (capacity), mission completion rates (inviter engagement).", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L158 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "917e8cef5c49e08b8b87e2cb4ac45de26fa644176663e2387261752173bb564b", "truncated": false}, "is_active": true}, {"id": "6f661b41-3781-5389-8bee-e4477d5985e3", "feature_slug": "resource-content-shared", "title": "Functions", "content": "### Admin CRUD (shared, `bff_` prefix)\n\n| Function | Type | Purpose |\n|---|---|---|\n| `bff_upsert_resource_content` | BFF | Create/update a resource (includes `p_platform_content`, `p_trigger_patterns`) |\n| `bff_get_resource_content_details` | BFF | Get single resource (new/edit mode) |\n| `bff_list_resource_content` | BFF | List resources with type, category, search, pagination filters |\n| `bff_delete_resource_content` | BFF | Delete a resource |\n| `bff_upsert_resource_content_category` | BFF | Create/update content category |\n| `bff_list_resource_content_categories` | BFF | List categories as parent/child tree |\n\n### Universal Delivery (shared, `fn_` prefix)\n\n| Function | Type | Purpose |\n|---|---|---|\n| `fn_resolve_resource_for_delivery` | Backend | Universal resolver: reads resource, checks channel restrictions, decides delivery_mode (platform_native / rich_content / text / media / link), returns full payload for messaging service |\n| `fn_render_blocks_as_text` | Backend | Text fallback renderer: converts rich_content blocks to plain text (for SMS, marketplace fallback, content preview) |\n\n### CS Send (CS-specific, `cs_` prefix)\n\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_send_resource` | BFF | BFF wrapper: validates merchant + conversation, calls cs_fn_send_resource |\n| `cs_fn_send_resource` | Backend | Uses `fn_resolve_resource_for_delivery`, inserts into `cs_messages` with full delivery context in metadata |\n| `cs_trigger_deliver_outbound_message` | Trigger | Fires on `cs_messages` INSERT, calls messaging service with resource-aware payload (delivery_mode, native_items, blocks) |\n\n### Edge Functions\n\n| Function | Type | Purpose |\n|---|---|---|\n| `browse-platform-catalog` | Edge | Universal (not CS-prefixed). Browses Shopee/Lazada/TikTok product catalogs using merchant_credentials. Returns normalized product list for admin catalog browser. |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Resource_Content.md#L274 Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "resource-content-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5ac07e4d482c049f94e8eb6a41787159b9dfab9c2c540bb40822d16b59525692", "truncated": false}, "is_active": true}, {"id": "8361ea23-3f8b-5345-8524-231e443d65bd", "feature_slug": "resource-content-shared", "title": "Tables", "content": "### `resource_content_category`\n\nMerchant-defined categories for organizing content. Supports one level of nesting.\n\n| Column | Type | Default | Notes |\n|---|---|---|---|\n| `id` | uuid | gen_random_uuid() | PK |\n| `merchant_id` | uuid NOT NULL | — | FK → merchant_master |\n| `category_name` | text NOT NULL | — | Display name |\n| `parent_id` | uuid | NULL | FK → self (one level nesting) |\n| `sort_order` | integer | 0 | |\n| `is_active` | boolean | true | |\n| `created_at` | timestamptz | now() | |\n| `updated_at` | timestamptz | now() | |\n\n### `resource_content`\n\nEvery piece of reusable sendable content. Shared entity — like `tag_master` for labels, this is for things you send.\n\n| Column | Type | Default | Notes |\n|---|---|---|---|\n| `id` | uuid | gen_random_uuid() | PK |\n| `merchant_id` | uuid NOT NULL | — | FK → merchant_master |\n| `resource_type` | text NOT NULL | — | `quick_reply`, `media`, `link`, `rich_content` |\n| `resource_code` | text | NULL | Human-readable identifier (unique per merchant) |\n| `name` | text NOT NULL | — | Admin/agent display name |\n| `content` | text | NULL | Text body (primary for quick_reply, description for others) |\n| `media_url` | text | NULL | Supabase Storage URL (for media type) |\n| `media_mime_type` | text | NULL | e.g. `application/pdf`, `video/mp4` |\n| `link_url` | text | NULL | External URL (for link type) |\n| `thumbnail_url` | text | NULL | Preview image |\n| `file_size_bytes` | integer | NULL | For media type |\n| `rich_content` | jsonb | ''{}'' | Structured blocks for rich_content type |\n| `category_id` | uuid | NULL | FK → resource_content_category |\n| `language` | text | NULL | ISO language code |\n| `search_tags` | text[] | ''{}'' | Freeform tags for search/filter |\n| `allowed_channels` | text[] | NULL | Channel restrictions. NULL = all. |\n| `is_active` | boolean | true | |\n| `sort_order` | integer | 0 | |\n| `platform_content` | jsonb | ''{}'' | Native platform catalog items selected by admin — see Platform Content section |\n| `metadata` | jsonb | ''{}'' | Extensible |\n| `created_by` | uuid | NULL | Admin who created it |\n| `created_at` | timestamptz | now() | |\n| `updated_at` | timestamptz | now() | |\n\n**Indexes:**\n- Unique: `(merchant_id, resource_code)` WHERE `resource_code IS NOT NULL`\n- `(merchant_id, resource_type, is_active)` for filtered listing\n- GIN on `search_tags`\n- `(merchant_id, category_id)` WHERE `category_id IS NOT NULL`\n\n### Additional Column (live, not yet in schema proposal)\n\n| Column | Type | Default | Notes |\n|---|---|---|---|\n| `trigger_patterns` | text[] | ''{}'' | Conversation patterns that suggest this resource (for auto-suggest to agent/AI) |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Resource_Content.md#L5 Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "resource-content-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "159b0004dd64f9189f97a5daeadc12628e700c52bbfe72033445b1e515845c7b", "truncated": false}, "is_active": true}, {"id": "4e94a49d-24d4-52b8-9af2-9605452a1686", "feature_slug": "resource-content-shared", "title": "Integration Points", "content": "- **CS Agent:** browses resources in reply composer, sends to customer\n- **CS AI:** `send_resource` tool in `cs_action_config` — AI proactively attaches resources\n- **AMP Workflows:** message nodes reference `content_resource_id` in `node_config`\n- **AMP AI Agent:** `send_resource` action type in `amp_agent_action`\n- **CS Messages:** `cs_messages.metadata` records `content_resource_id` when a resource is sent\n- **Knowledge Articles:** `cs_knowledge_articles.metadata` can reference attached resources", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Resource_Content.md#L265 Integration Points", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "resource-content-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e831b5a9120681025abcfc8479b6fdb1da5ad0dc7949f00df44ec827b3ddc6dc", "truncated": false}, "is_active": true}, {"id": "cc2bf0e7-6892-538c-8c07-d992f7eed2f0", "feature_slug": "resource-content-shared", "title": "Resource Content (Shared) Domain Reference", "content": "**Keywords:** resource_content, content_resource, quick_reply, canned_response, saved_reply, media_resource, pdf, video, link, rich_content, content_library, resource_category, sendable_content, trigger_patterns, send_resource, search_resources\n**Source:** `Resource_Content.md`\n**Tables:** `resource_content`, `resource_content_category`\n| Function | Type | Purpose |\n|---|---|---|\n| `bff_upsert_resource_content_category` | BFF | Create/update content category |\n| `bff_list_resource_content_categories` | BFF | List categories as tree |\n| `bff_upsert_resource_content` | BFF | Create/update a resource |\n| `bff_get_resource_content_details` | BFF | Get single resource (new/edit mode) |\n| `bff_list_resource_content` | BFF | List resources with filters, search, pagination |\n| `bff_delete_resource_content` | BFF | Delete a resource |\n| `cs_fn_search_resources` | Backend | Search resources during conversation (AI, service role) |\n| `cs_fn_match_resource` | Backend | Pattern-match message against `trigger_patterns` for auto-reply |\n| `cs_fn_send_resource` | Backend | Look up resource → validate channel → send as message (AI, service role) |\n| `cs_bff_search_conversation_resources` | BFF | Search resources during conversation (human agent, JWT auth) |\n| `cs_bff_send_resource` | BFF | Send resource in conversation (human agent, JWT auth) |\n| `cs_bff_search_conversation_knowledge` | BFF | Search knowledge articles during conversation (human agent, JWT auth) |\n**Key Business Rules (summary):**\n- Shared entity (no module prefix) — used by CS agents, CS AI, AMP workflows, AMP AI agents\n- Four resource types: `quick_reply`, `media`, `link`, `rich_content`\n- Categories support one level of nesting (parent + children)\n- `search_tags` array for freeform tagging and search\n- `allowed_channels` restricts which channels a resource can be sent on (NULL = all)\n- `trigger_patterns` array for auto-matching customer messages to resources (migrated from custom answers)\n- Custom answers migrated from `cs_knowledge_articles` to `resource_content` as quick_replies\n- Both AI and human agents use `cs_fn_search_resources` to find content, `cs_fn_send_resource` to deliver it", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/resource-content-shared.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "resource-content-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "10cb43576927ac301ff0fe15aba5affe96998c90227a2ef45acea2a9d4a83a46", "truncated": false}, "is_active": true}, {"id": "caa41862-6502-5464-b4be-580b65c998b1", "feature_slug": "reward-groups", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n\n| Page                         | Route Reference                   | BFF                                                                   |\n| ---------------------------- | --------------------------------- | --------------------------------------------------------------------- |\n| Reward Group List            | Loyalty → Rewards → Reward Groups | `bff_list_reward_groups` — now returns `is_featured` per row         |\n| Reward Group Form (New/Edit) | Reward Group List → New / Edit    | `bff_get_reward_group_details` (returns `is_featured`), `bff_upsert_reward_group_with_limits` (accepts `p_is_featured boolean DEFAULT false`) |\n\n\n**Creating a Reward Group:**\n\n1. From **Reward Group List**, click **New Group**.\n2. Enter Group Name and optional Group Code.\n3. In the **Members** panel, search and add rewards to the group.\n4. In the **Limits** panel, click **Add Limit**:\n  - Choose **Metric**: \"Reward Type\" for Max Distinct, \"Reward Quantity\" for Group Quantity.\n  - Set **Count**, **Scope**, and **Time Unit**.\n  - Add additional limit rows as needed (e.g., one Max Distinct row + one Group Quantity row).\n5. Click **Save**. System validates no `CONFLICTING_GROUP_LIMITS` condition. If conflict detected, save is blocked with an inline error.\n\n**Editing limits:** Open the group''s edit form, modify limit rows, save again. Changes apply immediately to future redemptions.\n\n**Deleting a group:** From the list, delete the group. All `transaction_limits` rows for the group are removed. Rewards are not deleted — they lose their group membership.\n\n> **Common mistake:** Setting Max Distinct = 2 and Group Qty = 1. This is blocked at save. Group Qty must always be ≥ Max Distinct when both are configured for the same scope.\n\n---", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/reward-groups.md#L72 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ad67898089f5a9f2a5d0ad9cd173235a96de8ad0dd4b77722dcc72fa366597ee", "truncated": false}, "is_active": true}, {"id": "f28237c9-d561-56be-9900-b339c89c8438", "feature_slug": "reward-groups", "title": "7. Business Rules", "content": "**Rule 1 — Distinct slot is consumed only by a new type.**\nA user''s distinct count increments by 1 only when `:reward_id` has never appeared in `reward_redemptions_ledger` for that user within the time window. Re-redemptions of the same type are free of the distinct limit.\n\n**Rule 2 — Max Distinct is user-scoped only.**\n`metric = distinct_reward` requires `scope = user`. Total-scope distinct counting is not supported.\n\n**Rule 3 — Conflicting limits are blocked at save, not at redemption.**\nIf `max_distinct > group_quantity` on the same group at the same user scope, `bff_upsert_reward_group_with_limits` rejects the configuration with `CONFLICTING_GROUP_LIMITS` (RWD019). No contradictory configuration ever reaches the redemption path.\n\n**Rule 4 — All three limits stack independently.**\nAt redemption time, `fn_check_reward_group_limits` checks all limit rows on all groups the reward belongs to. The member must pass every configured limit. Order: Reward Quota → Group Quantity → Max Distinct.\n\n**Rule 5 — Time windows are independent per limit row.**\nA group can have Max Distinct = 1 per year AND Group Qty = 5 per month. The annual distinct window and the monthly quantity window run independently.\n\n**Rule 6 — Group membership is per reward, not per group.**\n`reward_master.reward_group_ids UUID[]` stores which groups each reward belongs to. Adding a reward to a group is done on the reward''s config, not by editing the group. A reward can belong to 0, 1, or many groups simultaneously.\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L185 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "51a2b2dbafe4ef4d96778b35b00a0dafeaab6df784894c3fe79ed6fdcbd604f4", "truncated": false}, "is_active": true}, {"id": "c83f838e-5e04-5ca9-905c-e51020d93357", "feature_slug": "reward-groups", "title": "3. Configuration Reference", "content": "### Reward Group Fields\n\n\n| Field          | Type         | Required | Notes                                          |\n| -------------- | ------------ | -------- | ---------------------------------------------- |\n| Group Name     | Text         | Yes      | Display name shown in admin and error messages |\n| Group Code     | Text         | No       | Human-readable identifier, unique per merchant |\n| Description    | Text         | No       | Internal notes                                 |\n| Is Featured    | Boolean      | No       | Default false. When true, group is surfaced in a carousel/featured section on the member-facing catalog |\n| Member Rewards | Multi-select | Yes      | Rewards assigned to this group                 |\n\n\n### Limit Fields (per limit row on the group)\n\n\n| Field     | Values                               | Notes                                                            |\n| --------- | ------------------------------------ | ---------------------------------------------------------------- |\n| Metric    | `Reward Type` / `Reward Quantity`    | `Reward Type` = Max Distinct; `Reward Quantity` = Group Quantity |\n| Count     | Integer ≥ 1                          | The limit ceiling                                                |\n| Scope     | `Per User` / `Total`                 | Max Distinct only supports Per User                              |\n| Time Unit | Day / Week / Month / Year / All Time | Window for counting                                              |\n\n\n### Limit Combinations & What They Express\n\n\n| Goal                              | Configure                                          |\n| --------------------------------- | -------------------------------------------------- |\n| Pick 1 type, any qty per type     | Max Distinct = 1 (no Group Qty limit)              |\n| Pick 1 type, 1 unit only          | Max Distinct = 1 + Reward Quota = 1 on each reward |\n| Pick 2 types, any qty each        | Max Distinct = 2 (no Group Qty limit)              |\n| Pick up to M types, N total units | Max Distinct = M + Group Qty = N (N must ≥ M)      |\n| Total N units, any type mix       | Group Qty = N only (no Max Distinct)               |\n\n\n> **Guardrail:** Max Distinct = M + Group Qty = 1 on the same group at the same scope is rejected at save (`CONFLICTING_GROUP_LIMITS` / RWD019). You cannot pick 2 types if only 1 unit total is allowed.\n\n---", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/reward-groups.md#L31 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "30d3706eaa63e6344e0fabf262daeb63c80c3d7e6374b85a82cb5ac290d53419", "truncated": false}, "is_active": true}, {"id": "8def6ad1-54f5-59f6-a4f9-5562aceb01e1", "feature_slug": "reward-groups", "title": "2. Key Concepts", "content": "**Reward Group** — A named container grouping one or more rewards under shared limit enforcement. A reward may belong to multiple groups simultaneously. Example: \"Cinema Tickets\" containing Zone A, Zone B, Zone C rewards.\n\n**Max Distinct Reward** — A limit on the number of *distinct reward types* a user may redeem inside a group, within a given time window. Only `scope = user` is valid. Re-redeeming an already-chosen type does not consume an additional slot.\n\n**Group Quantity Limit** — A cap on the *total units* a user (or all users) may redeem across all rewards in the group combined. Uses `metric = quantity`, `entity_type = reward_group`.\n\n**Reward Quota Limit** — A cap on the *total units* of one specific reward a user (or all users) may redeem. Uses `metric = quantity`, `entity_type = reward`.\n\n`**transaction_limits.metric`** — The column that differentiates Max Distinct from Quantity limits. Values: `quantity` (default) or `distinct_reward`.\n\n**Distinct Slot** — One slot consumed when a user redeems a reward type for the first time within the time window. Subsequent redemptions of the same type do not consume another slot.\n\n`**CONFLICTING_GROUP_LIMITS`** — A save-time error raised when `max_distinct > group_quantity` on the same group at `scope = user`. This configuration is mathematically contradictory (e.g., \"pick 2 types\" but \"only 1 unit total\") and is blocked before it reaches members.\n\n---", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L13 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "66ccf5fa22cb002e522a7d83c51d4f461b28efa3b3803143126013c85da7af78", "truncated": false}, "is_active": true}, {"id": "4e59d59b-f81b-5370-ad29-e6b211082d26", "feature_slug": "reward-groups", "title": "6a. For Customer Success", "content": "**Onboarding script:** \"Reward Groups let you control which rewards a customer can pick together. If you have three seat zones and you only want a customer to choose one, create a group with those three rewards and set Max Distinct = 1.\"\n\n**FAQ:**\n\n- *\"A customer redeemed Zone A twice — is that a bug?\"* No. Repeat redemptions of the same type are allowed by Max Distinct. To prevent this, add a Reward Quota = 1 on Zone A itself.\n- *\"Why can''t I save my group?\"* If you see \"Conflicting Group Limits,\" your Max Distinct count is higher than your Group Quantity limit. Either raise Group Qty or lower Max Distinct.\n- *\"Can a reward be in two groups at once?\"* Yes. Each group enforces its own limits independently. The member must pass all groups'' checks to redeem.\n\n**Troubleshooting (member says they''re blocked unexpectedly):** Check the group''s Max Distinct and time window. The count is `COUNT(DISTINCT reward_id)` within the window — if the window is \"all time\" and the member redeemed this type a year ago, the slot is still consumed.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L132 6. Perspectives / 6a. For Customer Success", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "17aba59bfbbd2cf58cc3490c80e166a2393cb38879867832ead093c2e40182ce", "truncated": false}, "is_active": true}, {"id": "4c4e2388-0582-52c5-b198-453b7431756d", "feature_slug": "reward-groups", "title": "1. Overview", "content": "Reward Groups let merchants bundle multiple rewards together and control how members pick from that bundle — not just how many units they can take, but how many *types* they can choose. A member walking up to a \"Zone Tickets\" group with six seat categories shouldn''t be able to claim all six; Reward Groups enforce exactly that constraint.\n\nThe core mechanic is **Max Distinct Reward**: a per-group, per-user limit on the number of distinct reward types a member may redeem. A member who has already claimed \"Zone A\" seats cannot add \"Zone B\" if Max Distinct = 1 — but they can redeem more \"Zone A\" units as long as Zone A''s own quota allows it. Re-redeeming a type the member already owns never consumes an additional distinct slot.\n\nThis composes cleanly with two pre-existing limit types. Max Distinct answers \"which types can the user pick?\" Group Quantity answers \"how many total units across the group?\" Reward Quota answers \"how many units of this specific reward?\" All three are independent and stack: each check runs in sequence, and the member must pass all that are configured.\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "08e5048ff16c59aa2fafe1ba61d3d3f95cac05c1e7c8af0940a0679dab851009", "truncated": false}, "is_active": true}, {"id": "c01d4a1e-44e0-5d78-b5cb-9015a06122df", "feature_slug": "reward-groups", "title": "8. Business Use Cases (from image reference)", "content": "### Use Case 1 — Pick 1 type, any quantity per type\n\n> *\"เลือกตั๋วหนัง: Zone A 3 ใบ หรือ Zone B 4 ใบ\"*\n\nMember can choose only one zone, but can take multiple seats in that zone.\n\n\n| Config                 | Value                  |\n| ---------------------- | ---------------------- |\n| Rewards in group       | Zone A, Zone B, Zone C |\n| Max Distinct           | 1 (per user, all time) |\n| Group Qty Limit        | — (none)               |\n| Reward Quota on Zone A | 3 per user             |\n| Reward Quota on Zone B | 4 per user             |\n\n\nMember redeems Zone A × 3 → allowed (distinct = 1, Zone A quota = 3 ✓). Tries Zone B → blocked (distinct already at max).\n\n---\n\n### Use Case 2 — Pick 1 type, exactly 1 unit\n\n> *\"เลือกสายไหมหรือช็อกโกแลตได้อย่างใดอย่างหนึ่ง 1 ชิ้นเท่านั้น\"*\n\nMember picks one item from two options; no stacking of the same item.\n\n\n| Config                      | Value                     |\n| --------------------------- | ------------------------- |\n| Rewards in group            | Silk Scarf, Chocolate Box |\n| Max Distinct                | 1 (per user, all time)    |\n| Reward Quota on each reward | 1 per user                |\n\n\nMember redeems Silk × 1 → allowed. Tries Silk again → blocked by Reward Quota. Tries Chocolate → blocked by Max Distinct.\n\n---\n\n### Use Case 3 — Pick up to M types, any quantity each\n\n> *\"มีสินค้า 100 ประเภท สามารถเลือกได้ 3 ประเภท ประเภทละ 3 ชิ้น\"*\n\nMember can pick from a large catalog but is limited to 3 distinct types, up to 3 units each.\n\n\n| Config                      | Value                  |\n| --------------------------- | ---------------------- |\n| Rewards in group            | 100 rewards            |\n| Max Distinct                | 3 (per user, all time) |\n| Group Qty Limit             | — (none)               |\n| Reward Quota on each reward | 3 per user             |\n\n\nMember redeems A × 2, B × 3, C × 1 → all allowed (3 distinct types, each within quota). Tries D → blocked (distinct = 3 at max).\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L207 8. Business Use Cases (from image reference)", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "145a773e244c4a5ab3b2e489db89fcbc8098fae528b2c4c411a76ef0e3be0e51", "truncated": false}, "is_active": true}, {"id": "31ac5986-577d-510e-a144-0032fbbcfb55", "feature_slug": "reward-groups", "title": "9. Related Features", "content": "| Feature            | Connection                                                                                                                                        |\n| ------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------- |\n| Rewards            | Reward Groups enforce cross-reward limits on top of individual reward configs. See [rewards.md](rewards.md) for per-reward quota and eligibility. |\n| Transaction Limits | `transaction_limits` stores both per-reward and per-group limits. The `metric` column is what differentiates Max Distinct from Quantity.          |\n| Currency (Points)  | Points are deducted per-reward at the individual reward''s configured cost. Group limits do not affect points pricing.                             |\n| AMP Workflows      | Campaign-visibility rewards can be pushed into groups; group limits enforce redemption caps across push-delivered reward types.                   |", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L266 9. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "28e2743c3d483a437f441c86332746ed5c7386e16f08ec829760291ed732d183", "truncated": false}, "is_active": true}, {"id": "66bf098e-8d86-5cfe-9149-2291cdbe7beb", "feature_slug": "reward-groups", "title": "6c. For Testers", "content": "**Key assertions for `fn_check_reward_group_limits`:**\n\n\n| Scenario                                                          | Expected result                                                  |\n| ----------------------------------------------------------------- | ---------------------------------------------------------------- |\n| User redeems type A, distinct count = 0, Max Distinct = 1         | Allowed. Distinct count → 1                                      |\n| User redeems type B after A, distinct count = 1, Max Distinct = 1 | Blocked. RWD018                                                  |\n| User redeems type A again, distinct count = 1, Max Distinct = 1   | Allowed (same type, no new slot)                                 |\n| User redeems type B after A, Max Distinct = 2                     | Allowed. Distinct count → 2                                      |\n| User redeems type C after A+B, Max Distinct = 2                   | Blocked. RWD018                                                  |\n| Max Distinct = 2, Group Qty = 1 → save attempt                    | Blocked at save. RWD019                                          |\n| Max Distinct = 2, Group Qty = 3 → user redeems 3 units of A       | Allowed (passes Max Distinct=2 as same type; passes Group Qty=3) |\n| Reward belongs to 2 groups, each with Max Distinct = 1            | Both groups checked independently; both must pass                |\n| `metric` absent from old limit row                                | Coalesced to `quantity`; existing behavior unchanged             |\n\n\n**Error payload to assert (RWD018):**\n\n```json\n{\n  \"allowed\": false,\n  \"metric\": \"distinct_reward\",\n  \"title\": \"Reward type limit reached\",\n  \"limit_count\": 1,\n  \"current_count\": 1,\n  \"remaining\": 0\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L132 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "88b8109adcb43f808716310c115e54edfd516f0c7b4ccf5ec1ca561a944abfe4", "truncated": false}, "is_active": true}, {"id": "b8fd2ac3-55e4-5c8c-853d-ef46fad56ce9", "feature_slug": "reward-groups", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n\n| State            | Page                    | Notes                                                          |\n| ---------------- | ----------------------- | -------------------------------------------------------------- |\n| Browsing catalog | Reward Catalog          | `api_get_rewards_full_cached` returns `reward_group_ids[]` per reward and a top-level `groups{}` map with name, `is_featured`, and limits — no second round-trip needed |\n| Checking quota   | Reward Catalog / Detail | `api_get_my_reward_group_usage()` returns live quota per group including `redeemed_reward_ids[]` |\n| Chosen badge     | Reward Card             | Reward ID is in `redeemed_reward_ids` → green \"Chosen ✓\" — re-redeem allowed subject to individual reward quota |\n| Locked badge     | Reward Card             | Reward ID is NOT in `redeemed_reward_ids` AND `remaining = 0` → red \"Locked\" — group''s distinct limit is full |\n| Redeeming        | Reward Detail → Confirm | Limit check happens server-side at redemption time via `fn_check_reward_group_limits` |\n| Blocked          | Reward Detail           | Error drawer shown with remaining quota and limit description (RWD018) |\n| Featured group   | Reward Catalog          | Groups with `is_featured = true` are surfaced in a carousel section above the main grid |\n\n\n**Happy path (Max Distinct = 1, Group = Zone A / Zone B / Zone C):**\n\n1. Member opens **Reward Catalog** and taps Zone A.\n2. Taps **Redeem** — points deducted, Zone A redeemed. Distinct count = 1.\n3. Member opens Zone B. Taps **Redeem** — server calls `fn_check_reward_group_limits`, sees distinct count = 1, limit = 1 → **blocked**.\n4. Error drawer: *\"You can pick up to 1 distinct reward(s) in Cinema Tickets. You have already picked 1.\"*\n5. Member returns to Zone A and redeems again — same type, distinct count stays at 1 → **allowed** (subject to Zone A''s own Reward Quota).\n\n**Repeat redemption (same type, still allowed):**\n\nRedeeming Zone A a second time does not increment the distinct count. The group''s Max Distinct check sees `COUNT(DISTINCT reward_id)` = 1 and `is_new = false`, so no additional slot is consumed.\n\n---", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/reward-groups.md#L102 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ecb67ca047b18559cafd4f5c10fa385bb7ce6bfe2650f4fe139692034ec446de", "truncated": false}, "is_active": true}, {"id": "b15b0c07-da72-5e09-8d11-0929189c7ac1", "feature_slug": "reward-groups", "title": "6b. For Marketing", "content": "Reward Groups solve the \"pick one from the menu\" problem. Instead of showing members a single reward, you can present an entire reward category and guarantee each member walks away with only their one chosen type — creating scarcity and perceived exclusivity without complex eligibility rules. The \"Zone Tickets\" example is classic: members feel they have freedom of choice, but the business maintains strict control over which categories each customer enters.\n\nMax Distinct also supports \"choose 2 from 5\" mechanics — a proven engagement pattern in loyalty (gift-with-purchase, trial bundles) that''s previously required custom engineering per campaign.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/reward-groups.md#L132 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "reward-groups", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "70516364f2d4ebf5daf2b59086d33764457e8e7910d1b831046122953798374a", "truncated": false}, "is_active": true}, {"id": "393f1c9e-520a-5b93-bc61-baa1c010dd2c", "feature_slug": "reward-sourcing-services", "title": "4. Admin journey", "content": "**Catalog and program setup**\n\n- Browse the **partner reward catalog** and select SKUs to expose in the merchant’s program.\n- Map chosen rewards to **campaigns or catalogs**, set **points (coin) pricing**, including **tier-specific** pricing where the product supports dynamic rules.\n- Configure **stock or availability** where the reward is quantity-limited; set **reorder / alert thresholds** for physical or pre-loaded digital inventory.\n\n**Monitoring and reporting**\n\n- Monitor **stock levels** and redemption velocity.\n- Run **redemption reports** (by reward, tier, channel, period).\n- Optionally **trigger reorder** or partner replenishment when stock falls below threshold (operational process may be manual or integrated depending on deployment).\n\n**Member-facing outcome**\n\n- After redemption, members receive **wallet entries, codes, or delivery status** consistent with the reward type (instant digital vs shipped physical).\n\n---", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/reward-sourcing-services.md#L24 4. Admin journey", "metadata": {"source_doc_type": "curated_sub_feature_knowledge", "source_priority": "curated", "review_status": "editorial", "feature_slug": "reward-sourcing-services", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3525ebd1e4072313dcb7d497b4448f47da80b28c5e5e856f200634cbd4575829", "truncated": false}, "is_active": true}, {"id": "0e13f527-a467-574c-8c9f-d3eaf8f549e5", "feature_slug": "reward-sourcing-services", "title": "7. Business rules", "content": "**Economics**\n\n- **Pay-per-use (partner rewards):** The merchant is charged **only for rewards that members actually redeem**—no upfront inventory purchase for partner-sourced catalog items unless explicitly negotiated otherwise.\n- **Merchant-owned privileges:** Funded as **discounts or internal services**; **no third-party SKU procurement** for those items.\n\n**Fulfillment and SLAs (targets for proposals and SLAs—not hard-coded platform guarantees unless contracted)**\n\n| Type | Process | Typical SLA |\n| --- | --- | --- |\n| **Digital e-voucher** | Real-time or near–real-time procurement from partner/API; code or link delivered into wallet on redeem | **Instant** (target) |\n| **Physical reward** | Order to fulfillment partner → pick, pack, ship; tracking in app where available | **2–5 business days** standard; **up to ~14 days** for edge cases |\n| **Merchant-owned** | Configured in admin; issued as privilege/voucher at redeem | **Instant** |\n| **Flash / limited** | Pre-loaded finite stock; high concurrency with first-come-first-served semantics; fairness rules as designed per campaign | **Instant** for digital; physical follows physical row |\n\n**Partner operations**\n\n- **Onboarding:** New partners typically require **contracting, technical integration (API or file-based codes), and catalog configuration**—often quoted as **~5 business days** end-to-end when processes are mature (actual timeline varies).\n- **Seasonal / campaign partners:** Support limited-time collaborations with **scheduled** start/end in catalog visibility.\n- **Reconciliation:** **Monthly per-partner** reports: codes issued, redeemed, expired; **billing based on redeemed (and billable) volume** per agreement.\n\n**Category framing (illustrative coin bands—not product defaults)**\n\n| Category | Examples | Typical source | Illustrative coin range |\n| --- | --- | --- | --- |\n| **Core service privileges** | Consult discounts, referrals, pharmacy/lab credits | Merchant-owned | Wide band (program-specific) |\n| **On-site amenity** | Parking, F&B on campus, lounge | Merchant-owned | Lower band |\n| **Wellness** | Spa, fitness, supplements, IV, massage | Merchant + partner | Mid band |\n| **Dining** | National QSR / café / restaurant chains | Partner network | Mid band |\n| **Lifestyle** | Marketplaces, gift cards, entertainment, beauty | Partner network | Mid–upper band |\n| **Health product** | Supplements, skincare, devices | Partner network | Upper band |\n| **Premium / flash** | High-ticket electronics, luxury wellness | Partner network | High band |\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/reward-sourcing-services.md#L44 7. Business rules", "metadata": {"source_doc_type": "curated_sub_feature_knowledge", "source_priority": "curated", "review_status": "editorial", "feature_slug": "reward-sourcing-services", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "40ae4bb30087a31b3e4b9eca7858bd9a583a9fa834215fc76c33f374354b2cb6", "truncated": false}, "is_active": true}, {"id": "b7596748-03e3-5e77-9743-a1f48ee825f7", "feature_slug": "reward-sourcing-services", "title": "1. Overview", "content": "**Reward sourcing** is the practice of offering members a **curated partner catalog** (digital vouchers, physical goods, lifestyle and wellness brands) while the merchant pays **only when a member redeems**—not for pre-purchased inventory sitting on the balance sheet.\n\n**Reward pool (pay-per-use)**\n\n- **Partner-network rewards:** Large SKU breadth from integrated partners. **Digital e-vouchers** are issued in near real time at redemption. **Physical rewards** ship via a fulfillment partner with tracking surfaced to the member where the product supports it.\n- **Merchant-owned privileges:** Discounts, service vouchers, and on-site benefits configured directly in the loyalty program. These typically have **no third-party procurement cost**—value is funded by the merchant’s own services or margin.\n\n**Why it matters for non-retail programs**\n\nMany programs serve **episodic visits** (clinics, services, insurance, B2B renewals) rather than daily retail traffic. Rewards should support three aims:\n\n1. **Bring members back** — privileges that motivate a return visit (follow-up offers, check-up packages, pharmacy or ancillary credits).\n2. **Cross-sell services** — introduce adjacent services or departments with targeted privileges (segment-specific bundles, wellness add-ons).\n3. **Stay present between visits** — everyday lifestyle rewards (dining, coffee, marketplaces, wellness retail) so the brand remains relevant between touchpoints.\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/reward-sourcing-services.md#L5 1. Overview", "metadata": {"source_doc_type": "curated_sub_feature_knowledge", "source_priority": "curated", "review_status": "editorial", "feature_slug": "reward-sourcing-services", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8dde3918c1518d1da642b7a64e2c0e3dcfd66b25429394237ca18351349eb401", "truncated": false}, "is_active": true}, {"id": "1a68dd4c-9eb3-5c32-92a7-9517dd099ed0", "feature_slug": "reward-sourcing-services", "title": "9. Platform mapping and boundaries", "content": "**In-platform today (Rocket CRM loyalty)**\n\n- **Reward catalog and redemption** are modeled around **merchant-defined rewards**, **points pricing** (including tier/persona/tag dimensions where enabled), **promo code pools**, and **redemption / ledger** flows documented under the main **Rewards** feature.\n\n**Partner sourcing layer (service / integration)**\n\n- **Partner catalog browse, API procurement at redeem, fulfillment partner shipping, and partner billing reconciliation** are **operating-model and integration** concerns. They may be delivered as **professional services**, **partner integrations**, or **roadmapped product**—not all merchants have the same connector set.\n- When describing capabilities externally, distinguish **(A) native admin + ledger behavior** from **(B) sourced catalog and commercial SLAs** managed with partners.\n\n**Truth boundary**\n\n- Numeric claims in proposals (SKU counts, partner counts) should be **deal-specific** unless marketing has approved a **canonical** figure for the CRM knowledge base.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/feature-docs/reward-sourcing-services.md#L80 9. Platform mapping and boundaries", "metadata": {"source_doc_type": "curated_sub_feature_knowledge", "source_priority": "curated", "review_status": "editorial", "feature_slug": "reward-sourcing-services", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ead66d3adbc7fdd14ad354d674dcf67be78d0165743c1ddd5a324173405f1688", "truncated": false}, "is_active": true}, {"id": "7cd117b7-7bec-5671-bfb6-25bfd98849e2", "feature_slug": "rewards", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map** (update here if routes change — steps below reference page names only):\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Reward List | `/reward-list` | `api_get_rewards_full_cached()`, `admin_delete_reward()` |\n| Reward Settings (create) | `/reward-settings/new` | `bff_get_reward_details(mode=''new'')` |\n| Reward Settings (edit) | `/reward-settings/{id}` | `bff_get_reward_details(mode=''edit'', id)` |\n| Marketplace Settings | `/marketplace-settings` | `fetchMarketplaceChannels()` |\n\n### 4a. Create a New Reward\n\n1. From **Reward List**, click **\"Add reward\"** button\n2. **Reward Settings** opens in create mode — empty form\n3. Fill in Basic Info card: name (required), category, dates, expiry rules\n4. Set eligibility conditions: select allowed tiers, personas, birth months (leave empty for unrestricted)\n5. Configure points pricing: toggle `require_points_match`, set fallback points, add tier-specific rows via **\"Add tier\"** button\n6. Add transaction limits via **\"Add scope\"** button: set scope, time unit, count\n7. Fill display settings: headline, image upload, body/T&C/slip rich text editors\n8. Configure sidebar: visibility, promo code toggle, stock control + fulfillment method\n9. Optionally enable ecommerce platform → select platforms → bind Shopify discount\n10. Click **\"Save\"** (keeps current visibility) or **\"Save and Publish\"** (forces visibility to `user`)\n11. On success: toast \"Reward saved\", redirect to Reward List. On failure: error banner displayed.\n\n### 4b. Edit an Existing Reward\n\n1. From **Reward List**, click any reward row or the edit icon\n2. **Reward Settings** opens in edit mode — form pre-populated\n3. Modify any fields — all sections are editable\n4. Save or Save and Publish (same behavior as create)\n\n### 4c. Manage the Reward List\n\n1. **Reward List** displays an IndexTable with columns: Name, Visibility (badge), Redemption window, Points (dynamic/fallback/—), Stock (limited/unlimited), Actions\n2. **Filter/sort**: by visibility badge, name\n3. **Delete**: click delete icon → confirmation modal (\"Are you sure? Cannot be undone\")\n4. Empty state shows CTA to create first reward\n\n### 4d. Configure Marketplace Settings\n\n1. **Marketplace Settings** — tabbed page: \"Order Claims\" | \"Marketplace Connections\"\n2. **Marketplace Connections tab**: add channels (Shopify, Lazada, Shopee, TikTok), manage OAuth connections\n3. **Order Claims tab**: configure how marketplace orders link to loyalty accounts\n4. **Dashboard & History** button opens analytics modal\n\n### 4e. Common Admin Mistakes\n\n- Setting `require_points_match = true` with no conditions → no one can redeem\n- Enabling promo codes but not uploading any codes → redemptions fail with \"insufficient codes\"\n- Setting redemption window end date in the past → reward visible but unredeemable\n- Leaving visibility as `admin` and wondering why members can''t see the reward\n- Adding eligibility filters that exclude all current members → zero redemptions\n- Enabling stock control but not setting fulfillment method → confusing UX", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/rewards.md#L131 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "41262f67c258d85d18b0cf8c5a7fe86586790f653cad91ab019f635d043c44f4", "truncated": false}, "is_active": true}, {"id": "11747a39-d7db-5ab5-8d03-8224b76007f0", "feature_slug": "rewards", "title": "Dynamic Points Calculation", "content": "### Multi-Dimensional Matching System\n\nThe system evaluates FOUR dimensions to determine points required:\n\n```mermaid\ngraph TD\n    subgraph \"User Attributes\"\n        U1[Tier: Gold]\n        U2[Type: Buyer]\n        U3[Persona: Student]\n        U4[Tags: VIP, Early Adopter]\n    end\n    \n    subgraph \"Matching Process\"\n        M1[Find All Conditions]\n        M2[Evaluate Each Dimension]\n        M3[Calculate Specificity]\n        M4[Apply Priority Rules]\n        M5[Select Best Match]\n    end\n    \n    subgraph \"Condition Examples\"\n        C1[Gold + Buyer + Student + VIP<br/>Specificity: 4<br/>Points: 5]\n        C2[Gold + Buyer<br/>Specificity: 2<br/>Points: 15]\n        C3[Any + VIP Tag<br/>Specificity: 1<br/>Points: 10]\n        C4[Gold Tier Only<br/>Specificity: 1<br/>Points: 20]\n    end\n    \n    subgraph \"Result\"\n        R1[Selected: Condition 1<br/>Points Required: 5<br/>Most Specific Match]\n    end\n    \n    U1 --> M1\n    U2 --> M1\n    U3 --> M1\n    U4 --> M1\n    \n    M1 --> M2\n    M2 --> M3\n    M3 --> M4\n    M4 --> M5\n    \n    C1 --> M2\n    C2 --> M2\n    C3 --> M2\n    C4 --> M2\n    \n    M5 --> R1\n    \n    style U1 fill:#e3f2fd\n    style R1 fill:#c8e6c9\n```\n\n### Matching Logic Rules\n\n1. **Specificity First**: Conditions matching more dimensions take precedence\n2. **Priority Tiebreaker**: When specificity is equal, higher priority wins\n3. **Customer-Favorable**: When all else is equal, lowest points wins\n4. **Fallback Mechanism**: When no conditions match, use fallback_points\n\n### Calculation Flow\n\n```mermaid\nsequenceDiagram\n    participant User\n    participant System\n    participant Calculator\n    participant Conditions\n    participant Fallback\n    \n    User->>System: Request Redemption\n    System->>Calculator: calculate_redemption_points()\n    \n    Calculator->>Calculator: Get User Attributes\n    Note over Calculator: Tier, Type, Persona, Tags\n    \n    Calculator->>Conditions: Find Matching Conditions\n    Conditions->>Conditions: Evaluate All Dimensions\n    \n    alt Has Matching Conditions\n        Conditions->>Conditions: Sort by Specificity\n        Conditions->>Conditions: Apply Priority\n        Conditions->>Conditions: Select Lowest Points\n        Conditions-->>Calculator: Best Match Found\n        Calculator-->>System: Points from Condition\n    else No Match\n        Calculator->>Fallback: Check Fallback Config\n        alt Has Fallback Points\n            Fallback-->>Calculator: Use Fallback Points\n            Calculator-->>System: Fallback Points\n        else Require Match = True\n            Fallback-->>Calculator: No Fallback Allowed\n            Calculator-->>System: Error: No Match\n        else No Fallback, Not Required\n            Fallback-->>Calculator: Free Redemption\n            Calculator-->>System: 0 Points\n        end\n    end\n    \n    System->>User: Points Required Response\n```\n\n### Example Configurations\n\n#### Tiered Pricing with Persona Bonuses\n\n```sql\n-- Base tier pricing\nINSERT INTO reward_points_conditions (reward_id, tier_id, points_required, condition_name)\nVALUES \n    (''reward_uuid'', ''bronze_tier_uuid'', 100, ''Bronze Rate''),\n    (''reward_uuid'', ''silver_tier_uuid'', 80, ''Silver Rate''),\n    (''reward_uuid'', ''gold_tier_uuid'', 60, ''Gold Rate''),\n    (''reward_uuid'', ''platinum_tier_uuid'', 40, ''Platinum Rate'');\n\n-- Special persona rates\nINSERT INTO reward_points_conditions (reward_id, persona_id, points_required, priority, condition_name)\nVALUES \n    (''reward_uuid'', ''student_persona_uuid'', 50, 150, ''Student Discount''),\n    (''reward_uuid'', ''corporate_persona_uuid'', 70, 150, ''Corporate Rate'');\n\n-- VIP override (highest priority)\nINSERT INTO reward_points_conditions (reward_id, tag_ids, points_required, priority, condition_name)\nVALUES \n    (''reward_uuid'', ARRAY[''vip_tag_uuid''], 30, 200, ''VIP Special'');\n\n-- Fallback for unmatched users\nUPDATE reward_master \nSET fallback_points = 120, require_points_match = false\nWHERE id = ''reward_uuid'';\n```\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Reward.md#L1053 Dynamic Points Calculation", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "rewards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b34cbbf5b59980501661fd72ab90a20088197df39c4228f7dd8c26c3a00a1882", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

